from collections import deque

def bfs(grid, start, goal):
    h, w = len(grid), len(grid[0])
    q = deque([start])
    visited = {start}
    parent = {start: None}
    while q:
        r, c = q.popleft()
        if (r, c) == goal:
            return True
        for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < w and 0 <= nc < h and grid[nr][nc] != 1:
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    parent[(nr, nc)] = (r, c)
                    q.append((nr, nc))
    return False

```

