def dfs_grid(grid, start, goal):
    stack = [(start, [start])]
    while stack:
        (r, c), path = stack.pop()
        if (r, c) == goal:
            return path
        for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == 0 and (nr, nc) not in path:
                    stack.append(((nr, nc), path + [(nr, nc)]))
    return None

```

