```text
import heapq

def astar(start, goal, neighbors, h):
    pq = [(h(start), 0, start, [])]
    visited = set()
    while pq:
        f, g, node, path = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        if node == goal:
            return path + [node]
        for nxt, cost in neighbors(node):
            if nxt not in visited:
                ng = g + cost
                heapq.heappush(pq, (ng + h(nxt), ng, nxt, path + [node]))
    return None

```

