Student code/context:
```text
import heapq

def ucs(start, goal, graph, h):
    pq = [(0 + h[start], start, [])]
    visited = set()

    while pq:
        cost, node, path = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        path = path + [node]
        if node == goal:
            return path, cost
        for nbr, w in graph[node]:
            if nbr not in visited:
                heapq.heappush(pq, (cost + w + h[nbr], nbr, path))
    return None, float('inf')
```

